"""Count-min sketch with pairwise-independent-ish hashing built from blake2b."""

import math
from hashlib import blake2b


class CountMinSketch:
    """A count-min sketch supporting approximate frequency counting.

    Estimates are always >= the true count (one-sided error); with
    probability >= 1 - delta the overestimate is at most epsilon * total.
    """

    def __init__(self, width, depth, seed=0):
        if width <= 0 or depth <= 0:
            raise ValueError("width and depth must be positive")
        self.width = int(width)
        self.depth = int(depth)
        self.seed = int(seed)
        # Per-row salts derived from the seed make each row an
        # independent-ish hash function.
        self._salts = [
            blake2b(
                b"row:%d" % r,
                key=self.seed.to_bytes((self.seed.bit_length() + 7) // 8 or 1, "big"),
                digest_size=16,
            ).digest()
            for r in range(self.depth)
        ]
        self.table = [[0] * self.width for _ in range(self.depth)]
        self.total = 0

    @classmethod
    def from_error(cls, epsilon, delta, seed=0):
        """Build a sketch with overestimate <= epsilon * total with prob >= 1 - delta."""
        if epsilon <= 0 or not 0 < delta < 1:
            raise ValueError("need epsilon > 0 and 0 < delta < 1")
        width = math.ceil(math.e / epsilon)
        depth = math.ceil(math.log(1 / delta))
        return cls(width, depth, seed)

    def _row_hashes(self, item):
        """Yield the bucket index of `item` for each row."""
        data = str(item).encode("utf-8")
        return [
            int.from_bytes(blake2b(data, key=salt, digest_size=8).digest(), "big")
            % self.width
            for salt in self._salts
        ]

    def add(self, item, count=1):
        if count <= 0:
            raise ValueError("count must be positive")
        for row, idx in zip(self.table, self._row_hashes(item)):
            row[idx] += count
        self.total += count

    def estimate(self, item):
        return min(row[idx] for row, idx in zip(self.table, self._row_hashes(item)))

    def merge(self, other):
        """Merge another sketch into this one; both must share dimensions."""
        if not isinstance(other, CountMinSketch):
            raise TypeError("can only merge with another CountMinSketch")
        if self.width != other.width or self.depth != other.depth:
            raise ValueError(
                f"dimension mismatch: ({self.width}, {self.depth}) "
                f"vs ({other.width}, {other.depth})"
            )
        for row_a, row_b in zip(self.table, other.table):
            for i, v in enumerate(row_b):
                row_a[i] += v
        self.total += other.total
        return self

